// Keeps the head of a long list in view while the page scrolls.
angular.module("castra.core")
    .directive("stickyHeader", Directive);

Directive.$inject = [ "$window", "$document" ];

function Directive ($window, $document) {
    return {
        restrict: "A",
        link    : link
    };

    function link (scope, element, attrs) {
        var offset = attrs.stickyHeader === "top" ? 0 : 48;
        angular.element($window).on("scroll", function () {
            element.toggleClass("is-stuck", $document[0].documentElement.scrollTop > offset);
        });
    }
}
