// Moves the focus to the element as soon as it is rendered.
angular.module("castra.core")
    .directive("autoFocus", Directive);

Directive.$inject = [ "$timeout" ];

function Directive ($timeout) {
    return {
        restrict: "A",
        link    : link
    };

    function link (scope, element, attrs) {
        $timeout(function () {
            element[0].focus();
        });
    }
}
