// ui-router states of the rations area.
angular.module("castra")
    .config(config);

config.$inject = [ "$stateProvider" ];

function config ($stateProvider) {
    $stateProvider
        .state("rations", {
            url: "/rations",
            component: "rationBoard"
        })
        .state("rations.ledger", {
            url: "/ledger/:rationId",
            templateUrl: "app/ajs/features/rations/ration-ledger-page.html",
            controller: RationLedgerController,
            controllerAs: "$ctrl"
        })
        .state("rations.supply", {
            url: "/supply",
            template: "<supply-overview></supply-overview>"
        })
        .state("treasury", {
            url: "/treasury",
            template: "<treasury-page></treasury-page>"
        });
}

RationLedgerController.$inject = [ "rationService", "$stateParams" ];

function RationLedgerController (rationService, $stateParams) {
    var $ctrl = this;

    $ctrl.entry = { title: "", amount: 0, rationId: $stateParams.rationId };
    $ctrl.saving = false;
    $ctrl.notes = [];

    rationService.list().then(function (rations) {
        $ctrl.rations = rations;
    });

    $ctrl.touch = function () {
        $ctrl.dirty = true;
    };

    $ctrl.save = function () {
        $ctrl.saving = true;
        rationService.save($ctrl.entry).finally(function () {
            $ctrl.saving = false;
        });
    };
}
===== ./filters/castra.filters.js =====
// The filters every camp screen uses.
angular.module("castra.core")
    .filter("denarii", function () {
        return function (value, mode) {
            var amount = Number(value) || 0;
            return mode === "short" ? amount + " den." : amount + " denarii";
        };
    })
    .filter("padLeft", function () {
        return function (value, width) {
            var text = String(value);
            while (text.length < width) {
                text = " " + text;
            }
            return text;
        };
    })
    .filter("romanNumeral", function () {
        return function (value) {
            var numerals = [ "", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X" ];
            return value > 10 ? "X" + numerals[value - 10] : numerals[value];
        };
    })
    .filter("legionName", [ "legionService", function (legionService) {
        return function (legionId) {
            var legion = legionService.cached(legionId);
            return legion ? legionService.title(legion) : "unknown legion";
        };
    } ])
    .filter("cohortSize", function () {
        return function (value) {
            return (Number(value) || 0) + " men";
        };
    });
===== ./filters/format.filters.js =====
// Formatting filters for units, dates and long texts.
angular.module("castra.core")
    .filter("rationUnit", function () {
        return function (value, unit) {
            return (Number(value) || 0).toFixed(1) + " " + unit;
        };
    })
    .filter("shortDate", function () {
        return function (value) {
            return value ? new Date(value).toLocaleDateString() : "";
        };
    })
    .filter("truncate", function () {
        return function (value, length) {
            var text = String(value || "");
            return text.length > length ? text.slice(0, length) + "..." : text;
        };
    });
