// Helmets, shields and swords of the armory.
angular.module("castra.core")
    .service("armoryService", ArmoryService);

ArmoryService.$inject = [ "$http" ];

function ArmoryService ($http) {
    var service = this;
    var helmets = [];

    service.inventory = function () {
        return $http.get("/api/armory").then(function (response) {
            helmets = response.data.helmets;
            return response.data;
        });
    };

    service.shields = function () {
        return $http.get("/api/armory/shields").then(function (response) {
            return response.data;
        });
    };

    service.cachedHelmets = function () {
        return helmets;
    };

    service.frontRow = function (shields) {
        return shields.slice(0, Math.ceil(shields.length / 2));
    };

    service.rearRow = function (shields) {
        return shields.slice(Math.ceil(shields.length / 2));
    };

    service.pageCount = function (items) {
        return Math.ceil(items.length / 20);
    };
}
===== ./services/camp-clock.js =====
// The time in camp, refreshed once a minute.
angular.module("castra.core")
    .factory("campClock", campClock);

campClock.$inject = [ "$interval" ];

function campClock ($interval) {
    var time = "06:00";
    $interval(tick, 60000);

    return {
        now: now,
        tick: tick
    };

    function now () {
        return time;
    }

    function tick () {
        time = new Date().toTimeString().slice(0, 5);
    }
}
