// Reports in the old format. The Angular treasury page still reads them.
angular.module("castra.core")
    .factory("legacyReports", legacyReports);

legacyReports.$inject = [ "$http", "reportCache" ];

function legacyReports ($http, reportCache) {
    return {
        latest: latest,
        find: find
    };

    function latest () {
        return $http.get("/api/reports/latest").then(function (response) {
            return response.data;
        });
    }

    function find (reportId) {
        return reportCache.get(reportId) || $http.get("/api/reports/" + reportId);
    }
}
===== ./services/legion-service.js =====
// Legions and their cohorts, loaded once and kept in memory.
angular.module("castra.core")
    .service("legionService", LegionService);

LegionService.$inject = [ "$http", "$filter" ];

function LegionService ($http, $filter) {
    var service = this;
    var cache = {};
    // standardsRegistry used to keep the standards; they now arrive with each legion.

    service.list = function () {
        return $http.get("/api/legions").then(function (response) {
            response.data.forEach(function (legion) {
                cache[legion.id] = legion;
            });
            return response.data;
        });
    };

    service.find = function (legionId) {
        return $http.get("/api/legions/" + legionId).then(function (response) {
            return response.data;
        });
    };

    service.cached = function (legionId) {
        return cache[legionId];
    };

    service.title = function (legion) {
        return "Legio " + $filter("romanNumeral")(legion.number) + " " + legion.name;
    };

    service.totals = function (legionId) {
        return $http.get("/api/legions/" + legionId + "/totals").then(function (response) {
            return response.data;
        });
    };

    service.standardOf = function (legion) {
        return legion.number === 1 ? "eagle" : "vexillum";
    };
}
===== ./services/messenger-queue.js =====
// Messages for the couriers, sent in batches.
angular.module("castra.core")
    .factory("messengerQueue", messengerQueue);

messengerQueue.$inject = [ "$timeout" ];

function messengerQueue ($timeout) {
    var queue = [];

    return {
        push: push,
        flush: flush
    };

    function push (message) {
        queue.push(message);
    }

    function flush () {
        return $timeout(function () {
            queue.length = 0;
        }, 500);
    }
}
===== ./services/patrol-service.js =====
// The patrol log, the night watches and the tents.
angular.module("castra.core")
    .service("patrolService", PatrolService);

PatrolService.$inject = [ "$http", "$injector" ];

function PatrolService ($http, $injector) {
    var service = this;
    var entries = [];

    service.entries = function () {
        return $http.get("/api/patrols").then(function (response) {
            entries = response.data;
            return entries;
        });
    };

    service.cachedEntries = function () {
        return entries;
    };

    service.dismiss = function (entryId) {
        return $http.delete("/api/patrols/" + entryId);
    };

    service.watches = function () {
        return [ { id: 1, name: "Prima vigilia", start: "18:00", end: "21:00" } ];
    };

    service.tents = function () {
        return $http.get("/api/tents").then(function (response) {
            return response.data;
        });
    };

    service.rowsOf = function (tents) {
        var rows = [];
        for (var index = 0; index < tents.length; index += 8) {
            rows.push(tents.slice(index, index + 8));
        }
        return rows;
    };

    service.firstTent = function () {
        return { number: 1, occupants: 0, capacity: 8 };
    };

    service.campTime = function () {
        // Looked up when it is needed: the clock starts its timer as soon as it is created.
        return $injector.get("campClock").now();
    };
}
===== ./services/ration-service.js =====
// Rations and the ledger lines that pay for them.
angular.module("castra.core")
    .service("rationService", RationService);

RationService.$inject = [ "$http", "$q" ];

function RationService ($http, $q) {
    var service = this;

    service.list = function () {
        return $http.get("/api/rations").then(function (response) {
            return response.data;
        });
    };

    service.setAmount = function (rationId, amount) {
        return $http.put("/api/rations/" + rationId, { amount: amount });
    };

    service.remove = function (rationId) {
        return $http.delete("/api/rations/" + rationId);
    };

    service.save = function (entry) {
        return entry.title ? $http.post("/api/ledger", entry) : $q.reject("title");
    };

    service.balanceOf = function (entries) {
        return entries.reduce(function (sum, entry) {
            return sum + entry.amount;
        }, 0);
    };

    service.grainStore = function () {
        return { name: "Horreum", fill: 64, checkedAt: null };
    };
}
