// AngularJS services that Angular code still needs. Each one is read from the AngularJS injector under its registered name.

export abstract class LegacyReports {
    abstract latest(): Promise<unknown[]>;
}

export abstract class LegacyLegions {
    abstract list(): Promise<unknown[]>;
}

